create or replace function public.puede_gestionar_productos(usuario_id uuid default auth.uid())returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.perfil where id=usuario_id and rol='ADMINISTRADOR')$$;
create or replace function public.puede_gestionar_pedidos(usuario_id uuid default auth.uid())returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.perfil where id=usuario_id and rol='ADMINISTRADOR')$$;
create or replace function public.puede_consultar_pedidos(usuario_id uuid default auth.uid())returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.perfil where id=usuario_id and rol in('ADMINISTRADOR','TRABAJADOR'))$$;
revoke all on function public.puede_consultar_pedidos(uuid)from public;grant execute on function public.puede_consultar_pedidos(uuid)to authenticated;
drop policy if exists "gestor_pedidos_consultar_perfiles" on public.perfil;drop policy if exists "pedido_consultar_autorizado" on public.pedido;drop policy if exists "detalle_consultar_autorizado" on public.detalle_pedido;drop policy if exists "historial_consultar_autorizado" on public.historial_pedido;
create policy "operador_pedidos_consultar_perfiles" on public.perfil for select to authenticated using(public.puede_consultar_pedidos());
create policy "pedido_consultar_autorizado" on public.pedido for select to authenticated using(public.puede_consultar_pedidos()or cliente_id=auth.uid());
create policy "detalle_consultar_autorizado" on public.detalle_pedido for select to authenticated using(exists(select 1 from public.pedido p where p.id=pedido_id and(public.puede_consultar_pedidos()or p.cliente_id=auth.uid())));
create policy "historial_consultar_autorizado" on public.historial_pedido for select to authenticated using(exists(select 1 from public.pedido p where p.id=pedido_id and(public.puede_consultar_pedidos()or p.cliente_id=auth.uid())));
create or replace function public.cambiar_estado_pedido(p_pedido_id bigint,p_estado_nuevo text,p_observacion text default null)returns void language plpgsql security definer set search_path='' as $$declare v_anterior text;begin if not public.puede_consultar_pedidos()then raise exception 'NO_AUTORIZADO';end if;if p_estado_nuevo not in('RECIBIDO','EN_REVISION','EN_PRODUCCION','LISTO','ENTREGADO','CANCELADO')then raise exception 'ESTADO_INVALIDO';end if;select estado into v_anterior from public.pedido where id=p_pedido_id for update;if not found then raise exception 'PEDIDO_NO_EXISTE';end if;if v_anterior in('ENTREGADO','CANCELADO')then raise exception 'PEDIDO_FINAL';end if;if v_anterior=p_estado_nuevo then raise exception 'ESTADO_SIN_CAMBIO';end if;update public.pedido set estado=p_estado_nuevo,updated_at=now()where id=p_pedido_id;insert into public.historial_pedido(pedido_id,usuario_id,estado_anterior,estado_nuevo,observacion)values(p_pedido_id,auth.uid(),v_anterior,p_estado_nuevo,nullif(btrim(p_observacion),''));end;$$;
revoke all on function public.cambiar_estado_pedido(bigint,text,text)from public;grant execute on function public.cambiar_estado_pedido(bigint,text,text)to authenticated;
